args.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?composer ?composerLabel ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Billy_Elliot dbo:musicComposer ?composer .
  ?composer dbo:birthPlace ?birthPlace .
  OPTIONAL { ?composer rdfs:label ?composerLabel . FILTER(lang(?composerLabel) = "en") }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER(lang(?birthPlaceLabel) = "en") }
}

